class Weight
  attr_reader :amount, :unit

  def initialize(amount, unit)
    @amount = amount
    @unit = unit
  end

  def <=>(other)
    raise ArgumentError, "Comparison between different units" unless @unit == other.unit
    @amount <=> other.amount
  end

  def ==(other)
    return false unless other.is_a?(Weight)
    @amount == other.amount && @unit == other.unit
  end

  def clamp(min, max)
    raise ArgumentError, "Bounds not from same unit" unless @unit == min.unit && @unit == max.unit
    amount_clamped = @amount.clamp(min.amount, max.amount)
    Weight.new(amount_clamped, @unit)
  end

  def between?(min, max)
    raise ArgumentError, "Bounds not from same unit" unless @unit == min.unit && @unit == max.unit
    @amount.between?(min.amount, max.amount)
  end
end
