class Steps
  def initialize(from)
    @from = from
  end

  def each
    return enum_for(__method__) unless block_given?

    (@from).downto(1) { |n| yield n }
    self
  end

  def next
    if @current.nil?
      @current = @from
    else
      @current -= 1
    end

    if @current < 1
      raise StopIteration
    else
      @current
    end
  end

  class Enum
    def initialize(steps)
      @steps = steps
      @current = nil
    end

    def next
      @steps.next
    end

    def with_index
      return enum_for(:with_index) unless block_given?

      i = 0
      each { |val| yield [val, i]; i += 1 }
    end

    def to_a
      each.to_a
    end

    def each
      return @steps.each unless block_given?
      return enum_for(:each) { @steps.each }

      @steps.each { |val| yield val }
    end

    def rewind
      @current = nil
    end
  end

  def enum_for(method = :each, *args)
    Enum.new(self)
  end
end
