class Weight
  attr_reader :amount, :unit

  def initialize(amount, unit)
    @amount = amount
    @unit = unit
  end

  def ==(other)
    return false unless other.is_a?(Weight)
    amount == other.amount && unit == other.unit
  end

  def <=>(other)
    raise ArgumentError unless other.is_a?(Weight) && unit == other.unit
    amount <=> other.amount
  end

  def clamp(min, max)
    if min.is_a?(Weight) && max.is_a?(Weight)
      raise ArgumentError unless unit == min.unit && unit == max.unit
      Weight.new([amount, min.amount, max.amount].sort[1], unit)
    else
      Weight.new([[amount, min, max].sort[1]], unit)
    end
  end

  def between?(min, max)
    if min.is_a?(Weight) && max.is_a?(Weight)
      raise ArgumentError unless unit == min.unit && unit == max.unit
      amount >= min.amount && amount <= max.amount
    else
      amount >= min && amount <= max
    end
  end
